-- [jooq ignore start]
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
-- [jooq ignore stop]

CREATE TABLE "terms" ("id" uuid NOT NULL DEFAULT uuid_generate_v4(), "createdAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "updatedAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "type" character varying(30) NOT NULL, "version" character varying(40) NOT NULL, "title" character varying NOT NULL, "isRequired" boolean NOT NULL DEFAULT false, "effectiveFrom" TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT "UQ_fec97e3c1900fc4e8d427e1fd2b" UNIQUE ("type", "version"), CONSTRAINT "PK_33b6fe77d6ace7ff43cc8a65958" PRIMARY KEY ("id"));
CREATE TABLE "terms_consents" ("id" uuid NOT NULL DEFAULT uuid_generate_v4(), "createdAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "updatedAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "userId" uuid, "termsId" uuid, CONSTRAINT "UQ_fb6907eae0c8b785aea32ebd3b6" UNIQUE ("userId", "termsId"), CONSTRAINT "PK_f6c15ff2c131bffdc287999f155" PRIMARY KEY ("id"));
CREATE TABLE "users" ("id" uuid NOT NULL DEFAULT uuid_generate_v4(), "createdAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "updatedAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "deletedAt" TIMESTAMP WITH TIME ZONE, "role" character varying(20) NOT NULL DEFAULT 'CUSTOMER', "passwordHash" character varying NOT NULL, "communityBlockedAt" TIMESTAMP WITH TIME ZONE, "communityBlockedByUserId" uuid, "username" varchar(20) NOT NULL, CONSTRAINT "users_username_unique" UNIQUE ("username"), CONSTRAINT "PK_a3ffb1c0c8416b9fc6f907b7433" PRIMARY KEY ("id"));
CREATE TABLE "system_configs" ("configKey" character varying(80) NOT NULL, "configValue" text NOT NULL, "description" character varying, "updated_by_user_id" uuid, "updatedAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), CONSTRAINT "PK_629779e823a9cc065bf964a2415" PRIMARY KEY ("configKey"));
CREATE TABLE "admin_audit_logs" ("id" uuid NOT NULL DEFAULT uuid_generate_v4(), "createdAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "updatedAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "actor_user_id" uuid NOT NULL, "action" character varying NOT NULL, "targetType" character varying NOT NULL, "targetId" character varying, "description" character varying(500), CONSTRAINT "PK_de7a8fc2fbb525484c71a86bb96" PRIMARY KEY ("id"));
CREATE INDEX "idx_audit_action" ON "admin_audit_logs" ("action");
CREATE INDEX "idx_audit_target" ON "admin_audit_logs" ("targetType", "targetId", "createdAt");
CREATE INDEX "idx_audit_actor_created" ON "admin_audit_logs" ("actor_user_id", "createdAt");
CREATE TABLE "storage_upload_tickets" ("id" uuid NOT NULL DEFAULT uuid_generate_v4(), "createdAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "updatedAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "issued_by_user_id" uuid NOT NULL, "domain" character varying NOT NULL, "objectKey" character varying NOT NULL, "expectedSizeBytes" integer NOT NULL, "expectedContentType" character varying NOT NULL, "status" character varying NOT NULL DEFAULT 'ISSUED', "expiresAt" TIMESTAMP WITH TIME ZONE NOT NULL, "verifiedAt" TIMESTAMP WITH TIME ZONE, "failedAt" TIMESTAMP WITH TIME ZONE, CONSTRAINT "UQ_d2a28435998a31be244fec2a596" UNIQUE ("objectKey"), CONSTRAINT "PK_656f2a7a2ed9e636ad3c4e842d4" PRIMARY KEY ("id"));
