CREATE TABLE "product_variants" ("id" uuid NOT NULL DEFAULT uuid_generate_v4(), "createdAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "updatedAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "name" character varying NOT NULL, "priceAmount" integer NOT NULL DEFAULT '0', "priceCurrency" character varying(3) NOT NULL DEFAULT 'KRW', "stock" integer NOT NULL DEFAULT '0', "isDefault" boolean NOT NULL DEFAULT false, "productId" uuid, "active" boolean NOT NULL DEFAULT true, CONSTRAINT "UQ_1edbb278083e7043c0d178bbcb5" UNIQUE ("productId", "name"), CONSTRAINT "PK_281e3f2c55652d6a22c0aa59fd7" PRIMARY KEY ("id"));
