CREATE TABLE "product_images" ("id" uuid NOT NULL DEFAULT uuid_generate_v4(), "createdAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "updatedAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "objectKey" character varying(500) NOT NULL, "sortOrder" integer NOT NULL DEFAULT '0', "productId" uuid, CONSTRAINT "UQ_a47d8b28fa544e88fb805b3b330" UNIQUE ("productId", "sortOrder"), CONSTRAINT "PK_1974264ea7265989af8392f63a1" PRIMARY KEY ("id"));
CREATE TABLE "products" ("id" uuid NOT NULL DEFAULT uuid_generate_v4(), "createdAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "updatedAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "deletedAt" TIMESTAMP WITH TIME ZONE, "name" character varying NOT NULL, "description" text, "category" character varying(50), "visible" boolean NOT NULL DEFAULT false, CONSTRAINT "PK_0806c755e0aca124e67c0cf6d7d" PRIMARY KEY ("id"));
