CREATE TABLE "order_items" ("id" uuid NOT NULL DEFAULT uuid_generate_v4(), "createdAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "updatedAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "productNameSnapshot" character varying NOT NULL, "variantNameSnapshot" character varying NOT NULL, "thumbnailImageUrlSnapshot" character varying, "unitPriceAmount" integer NOT NULL DEFAULT '0', "quantity" integer NOT NULL DEFAULT '1', "status" character varying(30) NOT NULL DEFAULT 'PENDING_PAYMENT', "paidAt" TIMESTAMP WITH TIME ZONE, "shippedAt" TIMESTAMP WITH TIME ZONE, "canceledAt" TIMESTAMP WITH TIME ZONE, "refundedAt" TIMESTAMP WITH TIME ZONE, "orderId" uuid, "variantId" uuid, CONSTRAINT "UQ_c23a8332adde825b9c28af230af" UNIQUE ("orderId", "variantId"), CONSTRAINT "PK_005269d8574e6fac0493715c308" PRIMARY KEY ("id"));
