CREATE TABLE "orders" ("id" uuid NOT NULL DEFAULT uuid_generate_v4(), "createdAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "updatedAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "orderNo" character varying(40) NOT NULL, "status" character varying(30) NOT NULL DEFAULT 'PENDING_PAYMENT', "totalAmount" integer NOT NULL DEFAULT '0', "shippingCost" integer NOT NULL DEFAULT '0', "finalPaymentAmount" integer NOT NULL DEFAULT '0', "refundedAmount" integer NOT NULL DEFAULT '0', "currency" character varying(3) NOT NULL DEFAULT 'KRW', "buyerName" character varying NOT NULL, "buyerPhone" character varying NOT NULL, "shipName" character varying NOT NULL, "shipPhone" character varying NOT NULL, "shipPostalCode" character varying NOT NULL, "shipAddress1" character varying NOT NULL, "shipAddress2" character varying NOT NULL, "paidAt" TIMESTAMP WITH TIME ZONE, "canceledAt" TIMESTAMP WITH TIME ZONE, "refundedAt" TIMESTAMP WITH TIME ZONE, "userId" uuid, "paymentMethod" varchar(30) NOT NULL DEFAULT 'BANK_TRANSFER', CONSTRAINT "UQ_9e116d4adfd60229dc662a81b03" UNIQUE ("orderNo"), CONSTRAINT "PK_710e2d4957aa5878dfe94e4ac2f" PRIMARY KEY ("id"));
